function Find_Min(lst){
    if (lst.length === 0) return [];
    let minSum = Infinity;
    let minSubarray = [];
    let currentSum = 0;
    let currentSubarray = [];

    for (let i = 0; i < lst.length; i++) {
        currentSum += lst[i];
        currentSubarray.push(lst[i]);

        if (currentSum < minSum) {
            minSum = currentSum;
            minSubarray = currentSubarray.slice();
        }

        if (currentSum > 0) {
            currentSum = 0;
            currentSubarray = [];
        }
    }

    return minSubarray;
}

function Find_Min(lst) {
  if (lst.length === 0) return [];

  let minSum = Infinity;
  let currentSum = 0;
  let start = 0;
  let end = 0;
  let tempStart = 0;

  for (let i = 0; i < lst.length; i++) {
    currentSum += lst[i];
    if (currentSum < minSum) {
      minSum = currentSum;
      start = tempStart;
      end = i;
    }
    if (currentSum > 0) {
      currentSum = 0;
      tempStart = i + 1;
    }
  }

  return lst.slice(start, end + 1);
}

