function find_adverbs(text){
    const regex = /\b\w+ly\b/g;
    let match;
    let adverbs = [];
    while ((match = regex.exec(text)) !== null) {
        adverbs.push({
            adverb: match[0],
            start: match.index,
            end: match.index + match[0].length
        });
    }
    return adverbs;
}

function find_adverbs(text){
