function maxAverageOfPath(cost) {
    const N = cost.length;
    const dp = Array.from({ length: N }, () => Array(N).fill(-1));

    function getMaxAverage(x, y) {
        if (x === N - 1 && y === N - 1) {
            return cost[x][y];
        }
        if (dp[x][y] !== -1) {
            return dp[x][y];
        }
        let maxCost = -Infinity;
        if (x < N - 1) {
            maxCost = Math.max(maxCost, getMaxAverage(x + 1, y));
        }
        if (y < N - 1) {
            maxCost = Math.max(maxCost, getMaxAverage(x, y + 1));
        }
        dp[x][y] = cost[x][y] + maxCost;
        return dp[x][y];
    }

    const totalCost = getMaxAverage(0, 0);
    const numberOfCells = N * N;
    return totalCost / numberOfCells;
}

function maxAverageOfPath(cost) {
    const N = cost.length;
    const dp = Array.from({ length: N }, () => Array(N).fill(0));
    const sum = Array.from({ length: N }, () => Array(N).fill(0));

    dp[0][0] = cost[0][0];
    sum[0][0] = cost[0][0];

    for (let i = 1; i < N; i++) {
        dp[i][0] = dp[i - 1][0] + cost[i][0];
        sum[i][0] = sum[i - 1][0] + cost[i][0];
    }

    for (let j = 1; j < N; j++) {
        dp[0][j] = dp[0][j - 1] + cost[0][j];
        sum[0][j] = sum[0][j - 1] + cost[0][j];
    }

    for (let i = 1; i < N; i++) {
        for (let j = 1; j < N; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
            sum[i][j] = sum[i - 1][j] + sum[i][j - 1] - dp[i - 1][j - 1] + dp[i][j];
        }
    }

    return sum[N - 1][N - 1] / dp[N - 1][N - 1];
}

