}

function findFirstIndex(arr, x) {
    let start = 0, end = arr.length - 1;
    while (start <= end) {
        let mid = Math.floor((start + end) / 2);
        if ((mid === 0 || x > arr[mid - 1]) && arr[mid] === x) {
            return mid;
        } else if (x > arr[mid]) {
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }
    return -1;
}

