function encode(message) {
    const vowels = 'aeiou';
    const shift = 2;
    const swapCase = (char) => char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
    const replaceVowel = (vowel) => vowels[(vowels.indexOf(vowel) + shift) % vowels.length];

    return message.split('').map(char => {
        if (/[a-zA-Z]/.test(char)) {
            let swapped = swapCase(char);
            if (vowels.includes(swapped.toLowerCase())) {
                return replaceVowel(swapped);
            }
            return swapped;
        }
        return char;
    }).join('');
}

function encode(message){
    const vowels = 'aeiou';
    const vowelMap = { a: 'c', e: 'g', i: 'k', o: 'q', u: 'w' };

    return message.split('').map(char => {
        if (char.match(/[a-zA-Z]/)) {
            let swappedCase = char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
            if (vowels.includes(swappedCase.toLowerCase())) {
                return vowelMap[swappedCase.toLowerCase()];
            }
            return swappedCase;
        }
        return char;
    }).join('');
}

