function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n || k >= n || a[k] <= a[index]) {
        return 0;
    }

    let includeCurrent = a[index] + max_sum_increasing_subseq(a, n, index + 1, k + 1);
    let excludeCurrent = max_sum_increasing_subseq(a, n, index + 1, k);

    return Math.max(includeCurrent, excludeCurrent);
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n || k >= n) {
        return 0;
    }

    let include = 0;
    if (index === 0 || a[index] > a[index - 1]) {
        include = a[index] + max_sum_increasing_subseq(a, n, index + 1, k);
    }

    let exclude = max_sum_increasing_subseq(a, n, index + 1, k);

    if (k > index) {
        include = Math.max(include, a[index] + max_sum_increasing_subseq(a, n, index + 1, k));
    }

    return Math.max(include, exclude);
}

