function is_sorted(lst) {
  let duplicateCount = {};

  for (let i = 0; i < lst.length; i++) {
    if (duplicateCount[lst[i]]) {
      duplicateCount[lst[i]]++;
      if (duplicateCount[lst[i]] > 1) {
        return false;
      }
    } else {
      duplicateCount[lst[i]] = 1;
    }

    if (i > 0 && lst[i] < lst[i - 1]) {
      return false;
    }
  }

  return true;
}

