function is_Monotonic(A) {
    let increasing = true;
    let decreasing = true;

    for (let i = 1; i < A.length; i++) {
        if (A[i] > A[i - 1]) {
            decreasing = false;
        } else if (A[i] < A[i - 1]) {
            increasing = false;
        }
    }

    return increasing || decreasing;
}

function strange_sort_list(lst) {
  const sortedList = [...lst].sort((a, b) => a - b);
  const result = [];
  let left = 0;
  let right = sortedList.length - 1;
  while (left <= right) {
    if (left === right) {
      result.push(sortedList[left]);
    } else {
      result.push(sortedList[left], sortedList[right]);
    }
    left++;
    right--;
  }
  return result;
}

function amicable_numbers_sum(limit){
    function sum_of_divisors(n) {
        let sum = 1;
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) {
                sum += i;
                if (i !== n / i) {
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let sum = 0;
    for (let num = 2; num <= limit; num++) {
        let partner = sum_of_divisors(num);
        if (partner > num && sum_of_divisors(partner) === num) {
            sum += num;
        }
    }
    return sum;
}

function amicable_numbers_sum(limit){
    function sum_of_divisors(n) {
        let sum = 1; // Start with 1 because it's a divisor for all numbers
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) {
                sum += i;
                if (i !== n / i) {
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let sum = 0;
    for (let num = 2; num <= limit; num++) {
        let divSum = sum_of_divisors(num);
        if (divSum !== num && sum_of_divisors(divSum) === num) {
            sum += num;
        }
    }
    return sum;
}

function find_length(string){
