    for (let i = 0; i < string.length; i++) {
        if (string[i] === '0') {
            currentDiff++;
        } else {
            currentDiff--;
        }

        if (currentDiff < 0) {
            currentDiff = 0;
        }

        maxDiff = Math.max(maxDiff, currentDiff);
    }

    return maxDiff;
}

