function factorize(n){
    let factors = [];
    // Start with the smallest prime number
    for(let i = 2; i <= n; i++){
        while(n % i === 0){
            factors.push(i);
            n /= i;
        }
    }
    return factors;
}

function get_total_number_of_sequences(m, n) {
    const dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));

    for (let i = 1; i <= m; i++) {
        dp[i][1] = i;
    }

    for (let j = 2; j <= n; j++) {
        for (let i = 1; i <= m; i++) {
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
        }
    }

    return dp[m][n];
}

function get_total_number_of_sequences(m, n) {
    const dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));

    for (let i = 1; i <= m; i++) {
        dp[i][1] = i;
        for (let j = 2; j <= n; j++) {
            dp[i][j] = dp[i - 1][j] + dp[i / 2][j - 1];
        }
    }

    return dp[m][n];
}

